// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 0, type(uint128).max);
        address actor = address(0xABCD);
        vm.deal(actor, amount);
        uint256 before = __invmut_c_Acc_balance(actor);
        vm.prank(actor);
        c.Put{value: amount}(0);
        uint256 after_ = __invmut_c_Acc_balance(actor);
        assertTrue(after_ == before + amount, "balance must increase by deposited amount");
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
